const e = $input.first().json;
const wf = (e.workflow && e.workflow.name) || 'Unknown workflow';
const wfId = (e.workflow && e.workflow.id) || '';
const node = (e.node && e.node.name) || (e.execution && e.execution.lastNodeExecuted) || '';
const errObj = (e.execution && e.execution.error) || e.error || {};
const msg = errObj.message || JSON.stringify(e).slice(0, 800);
const stack = String(errObj.stack || errObj.description || '').slice(0, 1500);
return [{ json: {
  workflowName: wf, workflowId: wfId, nodeName: node, errorMessage: String(msg).slice(0, 500),
  subject: '[ShiftHub] Workflow error in ' + wf,
  message: [
    'A ShiftHub workflow failed.',
    '',
    'Workflow: ' + wf,
    'Node:     ' + (node || '(before first node / trigger)'),
    'Error:    ' + String(msg).slice(0, 500),
    '',
    stack ? ('Details:\n' + stack) : '',
    '',
    'Check Executions in n8n for the full trace. Failed confirmations mean staff were NOT reminded or NOT marked confirmed.',
  ].join('\n'),
} }];

const cfgRows = $('Read Settings').all().map((i) => i.json);
const cfg = {};
for (const r of cfgRows) { const k = String(r.key ?? '').trim(); if (k) cfg[k] = r.value ?? ''; }
const err = $('Format Error').first().json;
return [{ json: {
  ...err,
  supervisorEmail: cfg.supervisorEmail,
  supervisorTelegramChatId: cfg.supervisorTelegramChatId,
  fromEmail: cfg.fromEmail || '',
} }];
